package com.tihai.utils;
import org.springframework.stereotype.Service;import com.fasterxml.jackson.databind.*;import java.nio.file.*;import java.nio.charset.StandardCharsets;import java.util.*;import java.io.*;
@Service public class ReviewStore {
 private final Path file;private final ObjectMapper json=new ObjectMapper();private Map<String,Object> root;
 public ReviewStore(){this(com.tihai.utils.InstallRoot.path("data/review/library.json"));}
 public ReviewStore(Path path){file=path;try{root=Files.exists(file)?json.readValue(Files.readAllBytes(file),Map.class):new LinkedHashMap<>();}catch(IOException e){throw new IllegalStateException("复习题库文件无法读取，已停止写入以保留原文件",e);}root.putIfAbsent("courses",new LinkedHashMap<>());root.putIfAbsent("questions",new LinkedHashMap<>());root.putIfAbsent("wrong",new LinkedHashMap<>());root.putIfAbsent("references",new LinkedHashMap<>());}
 private Map<String,Map<String,Object>> map(String key){return (Map)root.get(key);}
 private void save()throws IOException{Files.createDirectories(file.getParent());Path temp=file.resolveSibling(file.getFileName()+".new");Files.write(temp,json.writeValueAsBytes(root));try{Files.move(temp,file,StandardCopyOption.REPLACE_EXISTING,StandardCopyOption.ATOMIC_MOVE);}catch(AtomicMoveNotSupportedException e){Files.move(temp,file,StandardCopyOption.REPLACE_EXISTING);}}
 public synchronized void course(String id,String name)throws IOException{Map<String,Object> c=map("courses").get(id);if(c==null){c=new LinkedHashMap<>();c.put("id",id);map("courses").put(id,c);}if(!name.equals(c.get("name"))){c.put("name",name);save();}}
 public synchronized void coverage(String id,Map<String,Object> state)throws IOException{Map<String,Object> c=map("courses").get(id);if(c!=null){c.put("coverage",new LinkedHashMap<>(state));save();}}
 public synchronized void add(String course,String kind,String unit,String source,List<Map<String,Object>> rows,int order)throws IOException{
  int n=0;for(Map<String,Object> row:rows){String key=UUID.nameUUIDFromBytes((course+"|"+kind+"|"+source+"|"+row.get("platformQuestionId")).getBytes(StandardCharsets.UTF_8)).toString();Map<String,Object> q=new LinkedHashMap<>(row);q.put("id",key);q.put("course",course);q.put("kind",kind);q.put("unit",unit);q.put("order",order*10000+n++);q.put("updatedAt",java.time.LocalDateTime.now().toString());Map<String,Object> old=map("questions").get(key);if(old!=null&&!fingerprint(old).equals(fingerprint(q)))map("references").remove(key);map("questions").put(key,q);}save();
 }
 private Map<String,Object> copy(Map<String,Object> value){return json.convertValue(value,Map.class);}
 public synchronized List<Map<String,Object>> courses(){List<Map<String,Object>> out=new ArrayList<>();for(Map<String,Object> c:map("courses").values()){Map<String,Object> row=copy(c);List<Map<String,Object>> qs=questions(String.valueOf(c.get("id")),false);row.put("count",qs.size());row.put("practiceCandidates",qs.stream().filter(q->eligible(q)).count());row.put("referenceCount",qs.stream().filter(q->Boolean.TRUE.equals(q.get("referenceAvailable"))).count());row.put("wrongCount",qs.stream().filter(q->Boolean.TRUE.equals(q.get("wrong"))).count());row.put("gradeable",qs.stream().filter(q->Boolean.TRUE.equals(q.get("gradeable"))).count());out.add(row);}return out;}
 public synchronized List<Map<String,Object>> questions(String course,boolean wrongOnly){List<Map<String,Object>> out=new ArrayList<>();for(Map<String,Object> q:map("questions").values())if(course.equals(q.get("course"))&&(!wrongOnly||map("wrong").containsKey(q.get("id")))){Map<String,Object> row=copy(q);decorate(row);row.put("wrong",map("wrong").containsKey(q.get("id")));if(map("wrong").containsKey(q.get("id")))row.put("wrongRecord",copy(map("wrong").get(q.get("id"))));out.add(row);}out.sort(Comparator.comparing((Map<String,Object> q)->String.valueOf(q.get("kind"))).thenComparingInt(q->((Number)q.get("order")).intValue()));return out;}
 public static boolean eligible(Map<String,Object> q){return !Boolean.TRUE.equals(q.get("needsVision"))&&Arrays.asList("single","multiple","judgement","fill").contains(q.get("type"));}
 private static String fingerprint(Map<String,Object> q){return q.get("title")+"|"+q.get("type")+"|"+q.get("options");}
 private void decorate(Map<String,Object> q){Map<String,Object> r=map("references").get(q.get("id"));boolean valid=r!=null&&fingerprint(q).equals(r.get("fingerprint"));q.put("referenceAvailable",valid);if(valid){q.put("referenceAnswer",r.get("answer"));q.put("referenceSource",r.get("source"));q.put("referenceCanonical",r.get("canonical"));q.put("referenceUpdatedAt",r.get("updatedAt"));}}
 public synchronized Map<String,Object> question(String course,String id)throws IOException{Map<String,Object> q=map("questions").get(id);if(q==null||!course.equals(q.get("course")))throw new IOException("题目不存在或不属于本课程");Map<String,Object> result=copy(q);decorate(result);return result;}
 public synchronized void reference(String course,String id,Map<String,Object> original,String answer,String source)throws Exception{
  Map<String,Object> q=question(course,id);if(!eligible(q)||!fingerprint(q).equals(fingerprint(original)))throw new IOException("题目变化或内容不完整");if(!Arrays.asList("题库参考答案","AI参考答案","学习通AI参考答案").contains(source))throw new IOException("未知答案来源");String canonical=ReviewParser.canonical((String)q.get("type"),answer,(List<String>)q.get("options"));if(canonical.trim().isEmpty())throw new IOException("未取得可用参考答案");Map<String,Object> r=new LinkedHashMap<>();r.put("answer",answer);r.put("canonical",canonical);r.put("source",source);r.put("fingerprint",fingerprint(q));r.put("updatedAt",java.time.LocalDateTime.now().toString());map("references").put(id,r);save();
 }
 public synchronized Map<String,Object> check(String course,String id,String raw)throws Exception{return check(course,id,raw,false);}
 public synchronized Map<String,Object> check(String course,String id,String raw,boolean allowReference)throws Exception{
  Map<String,Object> q=question(course,id);boolean official=Boolean.TRUE.equals(q.get("gradeable"));if(!official&&!(allowReference&&Boolean.TRUE.equals(q.get("referenceAvailable"))))throw new IOException("本题尚无可用答案");
  String source=official?"平台公布答案":String.valueOf(q.get("referenceSource"));String expected=String.valueOf(q.get(official?"canonicalAnswer":"referenceCanonical"));String display=String.valueOf(q.get(official?"platformAnswer":"referenceAnswer"));String answer=ReviewParser.canonical((String)q.get("type"),raw,(List<String>)q.get("options"));boolean correct=answer.equals(expected);
  if(!correct){Map<String,Object> w=map("wrong").get(id);if(w==null)w=new LinkedHashMap<>();w.put("attempts",((Number)w.getOrDefault("attempts",0)).intValue()+1);w.put("lastAnswer",answer);w.put("gradingSource",source);w.put("gradingAnswer",display);w.put("referenceGrading",!official);w.put("lastWrongAt",java.time.LocalDateTime.now().toString());map("wrong").put(id,w);save();}
  Map<String,Object> result=new LinkedHashMap<>();result.put("correct",correct);result.put("platformAnswer",official?display:"");result.put("gradingAnswer",display);result.put("explanation",q.get("explanation"));result.put("answerSource",source);result.put("referenceGrading",!official);result.put("wrongMarked",map("wrong").containsKey(id));return result;
 }
 public synchronized Map<String,Object> snapshot(String course){Map<String,Object> out=new LinkedHashMap<>();Map<String,Object> meta=map("courses").get(course);out.put("course",meta==null?new LinkedHashMap<>():copy(meta));out.put("questions",questions(course,false));out.put("schemaVersion",1);return out;}
}
